  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is warehouse robotics data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of real operating data that trains AMRs, picking robots, and unloading systems in live distribution centers, including LiDAR and camera runs, teleoperated picks, and 3D scans of pallets and totes across shifts and seasons."
        }
      },
      {
        "@type": "Question",
        "name": "Can you collect data in a live, operating warehouse?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. We schedule sessions around operations, follow the site's safety rules for mixed traffic, and record during the shifts and peak periods your robot will actually work."
        }
      },
      {
        "@type": "Question",
        "name": "How do you handle stretch wrap, clear totes, and reflective floors?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We treat them as coverage targets, capturing them deliberately with depth, LiDAR, and reference 3D scans so models learn what they look like to each sensor."
        }
      },
      {
        "@type": "Question",
        "name": "Do you collect piece-picking data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. We run teleoperated picking on your robot or ours across your SKU mix, recording wrist camera, depth, grasp pose, and outcome for every attempt."
        }
      },
      {
        "@type": "Question",
        "name": "How often should warehouse data be refreshed?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "At minimum before peak season and after major layout changes. Tagging data by layout version makes it clear when a refresh is needed."
        }
      },
      {
        "@type": "Question",
        "name": "Have you worked on warehouse autonomy before?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. Gamasome is the primary software delivery partner on the Unbox UAMR350 program, building the full autonomy stack and Fleet Manager for a warehouse robot."
        }
      }
    ]
  }
]
